
/**
 * Utilities
 * @namespace utils
 */
export default class utils {

    /**
     * Converted an elapsed amount of time to a human-readable string.
     * @method utils.timeToString
     * @param {number} ms - milliseconds
     * @return {string} Readable string
     */
    static timeToString(ms:number):string {
        if (ms === 0) {
            return '0.000s';
        }
        let x = ms / 1000;
        let seconds = Math.floor(x % 60);
        x /= 60;
        let minutes = Math.floor(x % 60);
        x /= 60;
        let hours = Math.floor(x % 24);
        x /= 24;
        let days = Math.floor(x);
        let result = {
            d: days,
            h: hours,
            m: minutes,
            s: seconds,
            ms: (ms % 1000)
        };
        const span = (amount, label) => {
            let result = amount;
            result += label[0];
            return result;
        };
        const msToString = (amount) => {
            let str = amount.toString();
            while(str.length < 3) {
                str = '0' + str;
            }
            return str;
        };
        let str = '';
        if (result.d) {
            str += span(result.d, 'day') + ', ';
        }
        if (result.h) {
            str += span(result.h, 'hour') + ', ';
        }
        if (result.m) {
            str += span(result.m, 'minute') + ', ';
        }
        str += result.s + '.' + msToString(result.ms) + 's';
        return str;
    }
}
