import * as minimist from 'minimist';
import * as path from 'path';
import * as fs from 'fs';
import * as fsx from 'fs-extra';
import * as chalk from 'chalk';
import {exec} from 'child_process';
import utils from './utils';
import findNodeModules = require('find-node-modules');

export interface SyncStageOptions {
    verbose?:boolean;
    force?:boolean;
    silent?:boolean;
    external?:boolean;
}

interface SyncDef {
    name: string;
    version: string;
    hitPath: string;
    parents: Array<string>;
    installedPaths: Array<string>;
    deps: Array<string>;
}

interface SyncManifest {
    [key:string]: SyncDef;
}

/**
 * Stage files of a skills to be synced to the robot
 * this doesn't actually do the transport, that's accomplished
 * by either jibo-sync or jibo-rsync.
 * @class SyncStage
 * @param {string} cwd - Directory to sync
 * @param {Object} [options] Optional arguments
 * @param {boolean} [options.force=false] Clean staged folder each time.
 * @param {boolean} [options.verbose=false] Run in verbose mode.
 * @param {boolean} [options.silent=false] Suppress all output messages.
 * @param {boolean} [options.external=false] Fetch dependencies from npm
 */
export default class SyncStage {

    /**
     * Name of the syncignore file
     * @name SyncStage.FILENAME
     * @type {string}
     * @readonly
     * @default '.syncignore'
     */
    public static FILENAME:string = '.syncignore';

    /**
     * Name of the default staged folder
     * @name SyncStage.FOLDER
     * @type {string}
     * @readonly
     * @default '.staged'
     */
    public static FOLDER:string = '.staged';

    /**
     * The absolute path to the current working directory to sync
     * @name SyncStage#cwd
     * @type {string}
     * @readonly
     */
    public cwd:string;

    /**
     * The absolute path to the staged folder
     * @name SyncStage#staged
     * @type {string}
     * @readonly
     */
    public staged:string;

    /**
     * Suppress all console messages
     * @name SyncStage#silent
     * @type {boolean}
     * @readonly
     */
    public silent:boolean;

    /**
     * Remove the staged folder before starting a new stage
     * @name SyncStage#force
     * @type {boolean}
     * @readonly
     */
    public force:boolean;

    /**
     * Run in verbose mode
     * @name SyncStage#verbose
     * @type {boolean}
     * @readonly
     */
    public verbose:boolean;

    /**
     * Fetch dependencies from npm to staged directory
     * @name SyncStage#external
     * @type {boolean}
     * @readonly
     */
    public external:boolean;

    /**
     * Elapsed time in milliseconds for section.
     * @name SyncStage#timer
     * @type {number}
     * @private
     */
    private timer:number;

    /**
     * Run the commandline version of SyncStage
     * @method SyncStage.cli
     * @static
     */
    public static cli(): void {
        const args:any = minimist(process.argv.slice(2), {
            boolean: [
                'verbose',
                'help',
                'silent',
                'force',
                'external'
            ],
            alias: {
                v: 'verbose',
                h: 'help',
                s: 'silent',
                f: 'force',
                e: 'external'
            }
        });

        // Check for help or invalid target
        if (args.help) {
            SyncStage.printHelp();
            return process.exit();
        }

        // Start a new sync
        const cwd = args._[0] || process.cwd();
        const stage = new SyncStage(cwd, args);
        stage.start();
    }

    /**
     * Print the help for
     * @method SyncStage.printHelp
     * @private
     */
    private static printHelp(): void {
        console.log('Usage: sync-stage [dir] [flags]');
        console.log('Parameters: ');
        console.log('  -h, --help : Show this help');
        console.log('  -s, --silent : Suppress console output');
        console.log('  -v, --verbose : Give a more verbose output');
        console.log('  -f, --force : Delete the output directory before starting');
        console.log('  -e, --external : Discard local dependencies and fetch from npm');

        console.log('\nExamples:');
        console.log('  sync-stage --verbose');
        console.log('  sync-stage /path/to/module --force');
    }

    /**
     * Constructor
     */
    constructor(cwd: string, options?:SyncStageOptions) {

        // Set the defaults
        options = Object.assign({
            verbose: false,
            force: false,
            silent: false,
            external: false
        }, options || {});

        this.cwd = path.resolve(cwd);
        this.staged = path.resolve(cwd, SyncStage.FOLDER);
        this.force = options.force;
        this.verbose = options.verbose;
        this.silent = options.silent;
        this.external = options.external;
        if (this.verbose) {
            console.log(options);
        }
    }

    /**
     * Begin the staging
     * @method SyncStage#start
     */
    public start(): Promise<void> {
        return new Promise<void>((resolve, reject) => {
            Promise.resolve().then(() => {
                // const nodeModulesPaths = findNodeModules(process.cwd());
                // const rootDirectory = fs.realpathSync(nodeModulesPaths[nodeModulesPaths.length-1]);

                if (this.force) {
                    this.startTimer('Cleaning output');
                    fsx.removeSync(this.staged);
                    this.stopTimer();
                }

                this.startTimer('Creating output');
                fsx.mkdirsSync(this.staged);
                this.stopTimer();

                this.startTimer('Copying target to output');
                this.copySync(this.cwd, this.staged);
                this.stopTimer();

                this.startTimer('Check syncDependencies');
                this.syncDependencies(this.staged);
                this.stopTimer();

                // let linked = null;
                if (this.external) {
                    this.startTimer('Installing dependencies from scratch');
                    return this.execute('npm install --production');
                } else {
                    this.startTimer('Get linked dependencies');
                    const localPromise = this.getLocal(this.cwd, {});
                    localPromise.then((localManifest) => {
                        this.stopTimer();

                        this.startTimer('Copying linked dependencies');
                        const stagedModules = path.join(this.staged, 'node_modules');
                        fsx.mkdirsSync(stagedModules);

                        const manifestPromise = this.installLocal(Object.keys(localManifest)[0], stagedModules, localManifest);
                        manifestPromise.then((finalManifest) => {
                            this.stopTimer();

                            if (this.verbose) {
                                console.log("Using dev dependencies -- no need to install");
                            }
                            return Promise.resolve();
                        });
                    });
                }

            }).then(() => {

                this.stopTimer();
                if (!this.silent) {
                    console.log(chalk.green('\nCompleted.\n'));
                }
                resolve();

            }).catch((error) => {

                // cleanup
                fsx.removeSync(this.staged);
                console.error(chalk.red('Error in script:'));
                console.error(chalk.red(error));
                reject(error);
            });
        });
    }

    /**
     * The `syncDependencies` field in the package.json is a list of packages
     * which should be consider dependencies if syncing this package.
     * @method SyncStage#syncDependencies
     * @private
     * @param {string} dir - Path to search for linked
     */
    private syncDependencies(dir:string): void {
        const pkgPath = path.join(dir, 'package.json');
        if (!fs.existsSync(pkgPath)) {
            return;
        }
        const pkg = fsx.readJsonSync(pkgPath);
        const sync = pkg.syncDependencies;
        const dev = pkg.devDependencies || {};
        const results = {};
        if (sync) {
            sync.forEach((name) => {
                if (dev[name]) {
                    results[name] = dev[name];
                }
            });
            pkg.dependencies = Object.assign(
                pkg.dependencies || {}, results
            );
            fsx.writeJsonSync(pkgPath, pkg);
        }
    }

    /**
     * Install local dependencies based on hierarchical dependency graph for root package
     * @method SyncStage#installLocal
     * @private
     * @param {string} packageKey - `name@version` key for current package
     * @param {string} installRoot - Path to root node_modules to install to
     * @param {SyncManifest} manifest - Manifest of package graph
     * @return {Promise<SyncManifest>} Updated package manifest
     */
    private async installLocal(packageKey:string,
                         installRoot:string,
                         manifest:SyncManifest): Promise<SyncManifest> {

        const thisPackage = manifest[packageKey];
        if (thisPackage) {
            for (const depKey of thisPackage.deps) {
                const depPkg = manifest[depKey];
                const rootPkgInstalled = fs.existsSync(path.join(installRoot, depPkg.name));
                if (!depPkg.installedPaths.length && !rootPkgInstalled) {
                    const installPath = path.join(installRoot, depPkg.name);
                    manifest[depKey].installedPaths.push(installPath);
                    this.doInstall(depKey, depPkg.hitPath, installPath);
                    manifest = await this.installLocal(depKey, installRoot, manifest);
                } else {
                    for (const parentInstallPath of thisPackage.installedPaths) {
                        if (!this.isResolvable(parentInstallPath, depPkg.name, depPkg.version)) {
                            const installPath = path.join(parentInstallPath, 'node_modules', depPkg.name);
                            if (manifest[depKey].installedPaths.indexOf(installPath) === -1) {
                                manifest[depKey].installedPaths.push(installPath);
                                this.doInstall(depKey, depPkg.hitPath, installPath);
                                manifest = await this.installLocal(depKey, installRoot, manifest);
                            }
                        }
                    }
                }
            }
        }
        return manifest;
    }

    /**
     * Perform install of versioned package
     * @param packageKey - "name@version" package key
     * @param src - src of package to install
     * @param dest - install destination
     */
    private doInstall(packageKey:string, src:string, dest:string) {
        this.copySync(src, dest);
        if (this.verbose) {
            console.log(`Installed ${packageKey} at ${dest}`);
        }
    }

    /**
     * Determine if package at specific version is resolveable from current directory
     * @param cwd - Directory to search from
     * @param packageName - Name of package to resolve
     * @param version - Specific version of package to resolve
     */
    private isResolvable(cwd:string, packageName:string, version:string): boolean {
        const nodeModulesPaths = findNodeModules(cwd);
        for (const lookupPath of nodeModulesPaths) {
            const modulePath = path.join(cwd, lookupPath, packageName);
            if (fs.existsSync(modulePath)) {
                const pkgPath = path.join(modulePath, 'package.json');
                const pkg = fsx.readJsonSync(pkgPath);
                if (pkg.version === version) {
                    return true;
                }
                break;
            }
        }

        return false;
    }

    /**
     * Get a map of all the local production dependencies so we can manually copy
     * over those dependencies.
     * @method SyncStage#getLocal
     * @private
     * @param {string} cwd - Path to search for linked
     * @param {SyncManifest} manifest - Current manifest of package graph
     * @return {Promise<SyncManifest>} Updated manifest of package graph
     */
    private async getLocal(cwd:string, manifest:SyncManifest): Promise<SyncManifest> {
        const pkgPath = path.join(cwd, 'package.json');
        const pkg = fsx.readJsonSync(pkgPath);
        const pkgKey = `${pkg.name}@${pkg.version}`;
        const dependencies = Object.assign(
            {},
            pkg.dependencies,
            pkg.optionalDependencies
        );

        if (Object.keys(dependencies).length === 0) {
            return manifest;
        }

        if (!manifest[pkgKey]) {
            manifest[pkgKey] = {
                name: pkg.name,
                version: pkg.version,
                hitPath: cwd,
                parents: [],
                installedPaths: [],
                deps: []
            };
        }

        const nodeModulesPaths = findNodeModules(cwd);
        for (const name in dependencies) {
            let exists = false;
            let hitPath;
            for (const lookupPath of nodeModulesPaths) {
                const modulePath = path.join(cwd, lookupPath, name);
                if (fs.existsSync(modulePath)) {
                    const depPkgPath = path.join(modulePath, `package.json`);
                    const depPkg = fsx.readJsonSync(depPkgPath);
                    const depKey = `${name}@${depPkg.version}`;
                    hitPath = fs.realpathSync(modulePath);
                    if (manifest[pkgKey].deps.indexOf(depKey) === -1) {
                        manifest[pkgKey].deps.push(depKey);
                    }
                    if (!manifest[depKey]) {
                        manifest[depKey] = {
                            name: name,
                            version: depPkg.version,
                            hitPath: hitPath,
                            parents: [pkgKey],
                            installedPaths: [],
                            deps: []
                        };
                    } else {
                        if (this.verbose) {
                            console.log(`${depKey} already exists!`);
                        }
                        exists = true;
                        if (manifest[depKey].parents.indexOf(pkgKey) === -1) {
                            manifest[depKey].parents.push(pkgKey);
                        }
                    }
                    break;
                }
            }
            if (this.verbose) {
                console.log(`Making manifest for ${pkgKey}`);
            }
            if (!exists) {
                manifest = await this.getLocal(hitPath, manifest);
            }
            if (this.verbose) {
                console.log(`Done making manifest for ${pkgKey}`);
            }
        }
        return manifest;
    }

    /**
     * Copy files from source to destination
     * @method SyncStage#copySync
     * @private
     * @param {string} source - Source directory
     * @param {string} dest - Destination directory
     */
    private copySync(source, dest) {
        source = path.join(source, path.sep);

        if (this.verbose) {
            console.log(`Copying -- \n\tFrom: ${source}\n\tTo: ${dest}`);
        }

        // Local syncignore file
        const syncignorePath = path.join(source, SyncStage.FILENAME);

        const depBinPath = path.join(source, 'node_modules/.bin');

        // List of regular expression to ignore when creating file list
        let ignorePatterns:RegExp[] = [];

        // List of absolute paths to ignore when creating file list
        let ignorePaths:string[] = [
            path.join(source, SyncStage.FOLDER),
            syncignorePath,
            depBinPath,
            path.join(source, 'node_modules')
        ];
        if (this.external) {
            ignorePaths.push(path.join(source, 'node_modules'));
        }

        // If there's a syncignore file, then we'll convert it's contents
        // into a list of paths and patterns of things to ignore
        if (fs.existsSync(syncignorePath)) {
            const syncignore = fs.readFileSync(syncignorePath, 'utf8')
                .split(/[\n\r]/g)
                .map(ignore => ignore.trim())
                .filter(ignore => !!ignore);
            ignorePatterns = ignorePatterns.concat(this.getGlobs(syncignore));
            ignorePaths = ignorePaths.concat(this.getPaths(syncignore, source));
        }

        fsx.mkdirsSync(dest);
        fsx.copySync(source, dest, {
            filter: (file) => {

                // Ignore anything matching an absolute path
                if (ignorePaths.indexOf(file) > -1) {
                    return false;
                }

                // Ignore anything matching a regexp pattern
                for (let i = 0; i < ignorePatterns.length; i++) {
                    if (file.match(ignorePatterns[i])) {
                        return false;
                    }
                }

                // Add everything else
                return true;
            }
        });
    }

    /**
     * Filter a list of paths that are globs only
     * @method SyncStage#getGlobs
     * @private
     * @param {Array<String>} syncignore - Syncignore list
     * @return {Array<RegExp>} List of expression to ignore
     */
    private getGlobs(syncignore):RegExp[] {

        return syncignore.filter(item => {

            // Select anything with a glob
            return item.indexOf('*') > -1;

        }).map(item => {

            // Convert glob path to regular expression
            // doing this once and caching is faster than using
            // minimatch, the previous implementation
            return new RegExp('\\b' + item
                .replace(/\//g, '\/')
                .replace(/\./g, '\\.')
                .replace(/([\/])?\*+([\/])?/g, '$1?.*$2')
                .replace(/^\?/, '') + '\\b' // add word boundries to be less greedy
            );
        });
    }

    /**
     * Filter a list of paths that are absolute paths only
     * @method SyncStage#getPaths
     * @private
     * @param {Array<string>} syncignore - Syncignore list
     * @param {string} cwd - Current directory
     * @return {Array<string>} List of absolute paths
     */
    private getPaths(syncignore, cwd):string[] {

        return syncignore.filter(item => {

            return item.indexOf('*') === -1;

        }).map(item => {

            item = item[0] === '/' ? item.substr(1) : item;
            return path.resolve(cwd, item);

        });
    }

    /**
     * Let the user now a section is starting
     * @method SyncStage#startTimer
     * @private
     * @param {string} message - human readable message
     */
    private startTimer(message): void {
        if (!this.silent) {
            this.timer = Date.now();
            process.stdout.write(chalk.white(message + ' ... '));
        }
    }

    /**
     * Stop the previous occurance of `startTimer`
     * @method SyncStage#stopTimer
     * @private
     */
    private stopTimer(): void {
        if (!this.silent) {
            const elapsed = utils.timeToString(Date.now() - this.timer);
            console.log(chalk.white('done.'), chalk.gray(elapsed));
        }
    }

    /**
     * Execute a commandline.
     * @param {string} command - Command to execute
     * @param {RegExp} cwd - Current working directory
     * @return {Promise} Promise when completed
     */
    private execute(command):Promise<void> {
        return new Promise<void>((resolve, reject) => {
            const child = exec(command, { cwd: this.staged }, (error, stdout, stderr) => {
                if (error) {
                    reject(error);
                    return;
                }
                resolve();
            });

            if (this.verbose) {
                child.stderr.pipe(process.stderr);
                child.stdout.pipe(process.stdout);
            }
        });
    }
}
